const data = $input.first().json;
const voiceAnalysis = $node["分析语音特征"]?.json || null;

// 根据语音分析结果选择合适的TTS语音
let voiceModel = 'nova'; // 默认
let voiceSpeed = 1.0;
let voiceDialect = null;

if (voiceAnalysis) {
  // 根据音调选择语音模型
  if (voiceAnalysis.pitch === 'high') {
    voiceModel = 'shimmer'; // 较高音
  } else if (voiceAnalysis.pitch === 'low') {
    voiceModel = 'onyx'; // 较低音
  }

  // 调整语速
  voiceSpeed = voiceAnalysis.speed || 1.0;
  voiceDialect = voiceAnalysis.dialect;
}

return {
  json: {
    ...data,
    voice_model_id: voiceModel,
    voice_speed: voiceSpeed,
    voice_dialect: voiceDialect
  }
};

const persona = $input.first().json;

// 生成初始记忆
const initialMemories = [
  {
    memory_type: 'preference',
    content: `用户创建了${persona.persona_type}类型的AI人格，名字叫${persona.persona_name}`,
    importance_score: 0.9
  }
];

// 如果有兴趣爱好，添加到记忆中
if (persona.interests && persona.interests.length > 0) {
  initialMemories.push({
    memory_type: 'preference',
    content: `${persona.persona_name}的兴趣爱好包括：${persona.interests.join('、')}`,
    importance_score: 0.8
  });
}

return {
  json: {
    persona_id: persona.persona_id,
    user_id: persona.user_id,
    memories: initialMemories
  }
};

